"""
S5 Symmetric Group Cayley Laplacian and Irreducible Representation Projection
=============================================================================
Computes the spectrum of the Cayley graph of the symmetric group S5 (order 120)
generated by adjacent transpositions (Coxeter generators), and derives algebraic projection invariants.

Authors: Shrikant Bhosale (Atmabhan Pandit)
"""

import itertools
import numpy as np
import networkx as nx
from scipy.linalg import eigvalsh
from typing import Tuple, Dict, Any


class S5ProjectionFramework:
    """
    S5 Symmetric Group Cayley Graph Spectral Analyzer.
    Order |S5| = 120.
    Irreducible representation dimensions: [1, 1, 4, 4, 5, 5, 6].
    Frobenius-Schur identity: sum(d_i^2) = 1 + 1 + 16 + 16 + 25 + 25 + 36 = 120.
    """
    def __init__(self):
        self.N = 120
        self.irrep_dims = [1, 4, 5, 6]  # Distinct non-trivial irrep dimensions
        self.all_irrep_dims = [1, 1, 4, 4, 5, 5, 6]
        self.G = self._generate_s5_cayley_graph()
        self.L = nx.laplacian_matrix(self.G).toarray().astype(np.float64)

    def _generate_s5_cayley_graph(self) -> nx.Graph:
        """
        Generates the Cayley graph of S5 using adjacent transpositions (i, i+1) for i in {0,1,2,3}.
        """
        elements = list(itertools.permutations(range(5)))
        elem_to_idx = {e: i for i, e in enumerate(elements)}
        G = nx.Graph()
        for e in elements:
            for i in range(4):
                neighbor = list(e)
                neighbor[i], neighbor[i+1] = neighbor[i+1], neighbor[i]
                G.add_edge(elem_to_idx[e], elem_to_idx[tuple(neighbor)])
        return G

    def compute_spectrum(self) -> np.ndarray:
        """Computes all 120 eigenvalues of the Cayley Laplacian."""
        return eigvalsh(self.L)

    def compute_projections(self) -> Tuple[np.ndarray, Dict[str, float]]:
        """
        Calculates spectral density, spectral gap, and algebraic projection scalars.
        """
        eigenvalues = self.compute_spectrum()
        lambda_max = float(np.max(eigenvalues))
        nonzero_evals = eigenvalues[eigenvalues > 1e-10]
        lambda_min_nonzero = float(np.min(nonzero_evals)) if len(nonzero_evals) > 0 else 0.0

        # Algebraic representation denominator: |S5| + d_standard^2 + d_trivial = 120 + 16 + 1 = 137
        alpha_em_denom = self.N + (self.irrep_dims[1]**2) + self.irrep_dims[0]

        projections = {
            'Atomic (alpha_EM)': 1.0 / float(alpha_em_denom),
            'Galactic (alpha_G)': 1.0 / (float(np.mean(eigenvalues)) * float(self.irrep_dims[2])),
            'Cosmic (Lambda)': (lambda_min_nonzero / lambda_max) * (1.0 / float(self.irrep_dims[3]))
        }
        return eigenvalues, projections
